(async()=>{
  const E=window.__echoes; const rows=[];
  for(let i=0;i<40;i++){
    const s=E.cmd('runState');
    if(s.active) E.cmd('endRun','victory');
    E.cmd('startRun');
    const v=E.cmd('runState');
    rows.push({modes:v.frame.modes.join(','), defendAt:v.frame.defendAt.join(','), sides:v.frame.sides.join(''), r1:v.rewardFor[1], mode1:v.mode, wallet:v.wallet, free:v.freeSkillSlots});
  }
  E.cmd('endRun','victory');
  const bad=rows.filter(r=>r.mode1!=='kill_all'||r.r1!=='skill'||r.defendAt.split(',').length!==2||/^1|,1$/.test(r.defendAt)||r.modes.split(',').filter(m=>m==='defend').length!==2||r.modes.split(',').filter(m=>m==='kill_all').length!==4||r.modes[r.modes.length-1]!=='s'&&false);
  const sides=rows.map(r=>r.sides);
  return {n:rows.length, bad, uniqueFrames:[...new Set(rows.map(r=>r.modes))], defendPositions:[...new Set(rows.map(r=>r.defendAt))].sort(), sideVariety:[...new Set(sides)].length, sample:rows.slice(0,4)};
})()
